@NoArgsConstructor // konstruktor BEZ argumentow (np. dla Hibernate/Jackson)
@AllArgsConstructor // konstruktor z JEDNYM parametrem dla KAZDEGO pola
class Employee {
    @NonNull
    private String name; // wymagane pole
    private int age;     // opcjonalne
}

// @RequiredArgsConstructor wygenerowalby konstruktor TYLKO dla 'name' (@NonNull)

@Builder
class Product {
    String name;
    double price;
    String category;
}

Product product = Product.builder()
    .name("Monitor")
    .price(1299.99)
    .category("Elektronika")
    .build();

@Value
class ImmutablePoint {
    int x;
    int y;
}
// wszystkie pola final, klasa final, BRAK setterow

// BLAD: inicjalizator pola zignorowany przez Buildera bez @Builder.Default
@Builder
class Order {
    private String product;
    private int quantity = 1; // IGNOROWANE przez Buildera bez adnotacji!
}

Order order = Order.builder().product("Ksiazka").build();
System.out.println(order.getQuantity()); // 0, NIE 1!

// POPRAWNIE: @Builder.Default zachowuje wartosc inicjalizatora
@Builder
class Order {
    private String product;
    @Builder.Default
    private int quantity = 1; // uzyte, jesli nie ustawiono jawnie
}

Order order = Order.builder().product("Ksiazka").build();
System.out.println(order.getQuantity()); // 1, zgodnie z oczekiwaniem
